-- Drawing Hub bundle: hub + Free Draw, Spray Paint!, Draw Me!, Hide In Paintings and WELDING Bricklayer scripts in ONE file. Share this file as is.
-- Run it anywhere: pick a game, it teleports you there, re-runs itself after the join and starts that
-- game's drawer. Run it inside a listed game and the drawer starts right away (RightCtrl shows the hub).
-- Note: some games (Free Draw) block teleports to other creators' games; join those from the Roblox app.
local SRC = [===[
-- Drawing Game Hub (inner program; the bundle wrapper passes our own source as the first argument so we
-- can queue ourselves to run again after a teleport). The drawers are embedded in PAYLOADS below.
local SRC: string = ...

if not game:IsLoaded() then
	game.Loaded:Wait()
end

----------------------------------------------------------------------------------------------------
-- Re-execution guard
----------------------------------------------------------------------------------------------------
local genv: any = if type(getgenv) == "function" then getgenv() else _G
if genv.__DRAW_HUB and type(genv.__DRAW_HUB.Cleanup) == "function" then
	pcall(genv.__DRAW_HUB.Cleanup)
end

