local function section(title: string, hint: string)
	create("Frame", { -- divider
		BackgroundColor3 = THEME.Stroke,
		BackgroundTransparency = 0.4,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 1),
