	setOrbit(not state.orbitOn)
	orbitBtn.Text = if state.orbitOn then "Orbit: On  (O)" else "Orbit: Off  (O)"
	orbitStroke.Color = if state.orbitOn then Theme.Accent else Theme.Stroke
