----------------------------------------------------------------------------------------------------
-- Maid
----------------------------------------------------------------------------------------------------
local maid = { tasks = {} }
local function give(item: any): any
	table.insert(maid.tasks, item)
	return item
end
local function cleanupMaid()
	local tasks = maid.tasks
	maid.tasks = {}
	for i = #tasks, 1, -1 do
		local item = tasks[i]
		local kind = typeof(item)
		if kind == "RBXScriptConnection" then
			item:Disconnect()
		elseif kind == "Instance" then
			pcall(item.Destroy, item)
		elseif kind == "function" then
			pcall(item)
		elseif kind == "Tween" then
			item:Cancel()
		end
	end
end

