-- Launching
----------------------------------------------------------------------------------------------------
local function currentGame(): GameEntry?
	for _, entry in GAMES do
		if entry.placeId == game.PlaceId then
			return entry
		end
	end
	return nil
end

-- Runs an embedded drawer. Returns ok, err.
local function runScript(file: string): (boolean, string?)
	local source = PAYLOADS[file]
	if not source then
		return false, `{file} is not embedded in this bundle`
	end
	local fn, err = loadstring(source, file)
	if not fn then
		return false, `{file} failed to compile: {err}`
	end
	local okRun, runErr = pcall(fn)
	if not okRun then
		return false, `{file} errored: {runErr}`
	end
	return true, nil
end

-- Teleports to `entry` and re-runs this hub after the join (the hub then launches the game's script).
local function joinGame(entry: GameEntry): (boolean, string?)
	if Exec.queue then
		pcall(Exec.queue, RELAUNCH)
	else
		warn("[DrawHub] no queue_on_teleport: run the hub again once you're in the game")
	end
	local ok, err = pcall(TeleportService.Teleport, TeleportService, entry.placeId, LocalPlayer)
	if not ok then
		return false, tostring(err)
	end
	return true, nil
end

-- Some games (Free Draw among them) refuse teleports to other creators' games: Roblox reports it here.
local teleportFailed: ((string) -> ())? = nil
give(TeleportService.TeleportInitFailed:Connect(function(_, result: Enum.TeleportResult, message: string)
	local clear = if type(clearteleportqueue) == "function" then clearteleportqueue
		elseif type(clear_teleport_queue) == "function" then clear_teleport_queue
		else nil
	if clear then
		pcall(clear) -- don't leave the relaunch queued for a teleport that never happens
	end
	if teleportFailed then
		teleportFailed(if result == Enum.TeleportResult.Unauthorized
			then "this game blocks teleports to other creators' games. Join it from the Roblox app, then run this script again and the drawer starts by itself."
			else `{result.Name}: {message}`)
	end
end))

----------------------------------------------------------------------------------------------------
-- UI
----------------------------------------------------------------------------------------------------
local function create(className: string, props: { [string]: any }, children: { Instance }?): any
	local inst = Instance.new(className)
	local parent = props.Parent
	for key, value in props do
		if key ~= "Parent" then
			(inst :: any)[key] = value
		end
	end
	if children then
		for _, child in children do
			child.Parent = inst
		end
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local hostOk, host = pcall(function()
	return if Exec.gethui then Exec.gethui() else CoreGui
end)
if not hostOk or not host then
	host = LocalPlayer:WaitForChild("PlayerGui")
end

local screen = give(create("ScreenGui", {
	Name = "DrawHub",
	ResetOnSpawn = false,
	ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	DisplayOrder = 60,
	IgnoreGuiInset = true,
	Parent = host,
}))

local window = create("Frame", {
	Name = "Window",
	AnchorPoint = Vector2.new(0.5, 0),
	Position = UDim2.new(0.5, 0, 0, 80), -- top centre, so it never covers the tool window on the left
	Size = UDim2.fromOffset(Theme.Width, 0),
	AutomaticSize = Enum.AutomaticSize.Y,
	BackgroundColor3 = Theme.Bg,
	BorderSizePixel = 0,
	Active = true,
}, {
	create("UICorner", { CornerRadius = UDim.new(0, 12) }),
	create("UIStroke", { Color = Theme.Stroke, Thickness = 1 }),
})

local titleBar = create("Frame", {
	Size = UDim2.new(1, 0, 0, 40),
	BackgroundTransparency = 1,
	Active = true,
	Parent = window,
}, {
	create("TextLabel", {
		Size = UDim2.new(1, -24, 1, 0),
		Position = UDim2.fromOffset(14, 0),
		BackgroundTransparency = 1,
		Text = "Drawing Hub  -  pick a game",
		TextColor3 = Theme.Text,
		FontFace = Theme.FontBold,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
	}),
	create("TextLabel", {
		Size = UDim2.new(1, -28, 1, 0),
		Position = UDim2.fromOffset(14, 0),
		BackgroundTransparency = 1,
		Text = "RightCtrl shows / hides",
		TextColor3 = Theme.SubText,
		FontFace = Theme.Font,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Right,
	}),
})

local body = create("Frame", {
	Position = UDim2.fromOffset(0, 40),
	Size = UDim2.new(1, 0, 0, 0),
	AutomaticSize = Enum.AutomaticSize.Y,
	BackgroundTransparency = 1,
	Parent = window,
}, {
	create("UIPadding", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14), PaddingBottom = UDim.new(0, 14) }),
	create("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
})

local status = create("TextLabel", {
	Size = UDim2.new(1, 0, 0, 0),
	AutomaticSize = Enum.AutomaticSize.Y,
	BackgroundTransparency = 1,
	Text = "Choose a game below. Join takes you there and the drawing tool opens by itself when you arrive. If you're already in a game, press Start.",
	TextColor3 = Theme.SubText,
	FontFace = Theme.Font,
	TextSize = 12,
	TextWrapped = true,
	TextXAlignment = Enum.TextXAlignment.Left,
	LayoutOrder = 1,
	Parent = body,
})

local function setStatus(text: string, color: Color3?)
	status.Text = text
	status.TextColor3 = color or Theme.SubText
end

local function hoverTween(button: GuiObject, base: Color3, hover: Color3)
	local active: Tween? = nil
	local function to(color: Color3)
		if active then
			active:Cancel()
		end
		active = TweenService:Create(button, Theme.Tween, { BackgroundColor3 = color })
		active:Play()
	end
	give(button.MouseEnter:Connect(function()
		to(hover)
	end))
	give(button.MouseLeave:Connect(function()
		to(base)
	end))
	give(function()
		if active then
			active:Cancel()
		end
	end)
end

local here = currentGame()
local busy = false

-- One card per game: name, blurb, and a Join / Run button depending on where we are.
for i, entry in GAMES do
	local isHere = here == entry
	local hasFile = PAYLOADS[entry.file] ~= nil
	local card = create("Frame", {
		Size = UDim2.new(1, 0, 0, 64),
		BackgroundColor3 = Theme.Panel,
		BorderSizePixel = 0,
		LayoutOrder = 1 + i,
		Parent = body,
	}, {
		create("UICorner", { CornerRadius = Theme.Corner }),
		create("UIStroke", { Color = if isHere then Theme.Accent else Theme.Stroke, Thickness = 1 }),
		create("TextLabel", {
			Position = UDim2.fromOffset(12, 9),
			Size = UDim2.new(1, -130, 0, 18),
			BackgroundTransparency = 1,
			Text = entry.name .. (if isHere then "   (you are here)" else ""),
			TextColor3 = Theme.Text,
			FontFace = Theme.FontBold,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
		}),
		create("TextLabel", {
			Position = UDim2.fromOffset(12, 30),
			Size = UDim2.new(1, -130, 0, 16),
			BackgroundTransparency = 1,
			Text = if hasFile then entry.blurb else `{entry.file} is not embedded`,
			TextColor3 = if hasFile then Theme.SubText else Theme.Danger,
			FontFace = Theme.Font,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
		}),
	})
	local base = if isHere then Theme.Good else Theme.Accent
	local button = create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.fromOffset(104, 34),
		BackgroundColor3 = base,
		AutoButtonColor = false,
		BorderSizePixel = 0,
		Text = if isHere then "Start tool" else "Join game",
		TextColor3 = Theme.Text,
		FontFace = Theme.FontBold,
		TextSize = 13,
		Parent = card,
	}, {
		create("UICorner", { CornerRadius = Theme.Corner }),
	})
	hoverTween(button, base, base:Lerp(Color3.new(1, 1, 1), 0.18))
	give(button.Activated:Connect(function()
		if busy then
			return
		end
		busy = true
		if isHere then
			setStatus(`Starting the {entry.name} tool…`, Theme.Text)
			local ok, err = runScript(entry.file)
			setStatus(if ok then `{entry.name} tool is open. Press RightCtrl to hide this window.` else `Error: {err}`, if ok then Theme.Good else Theme.Danger)
		else
			setStatus(`Teleporting to {entry.name}… this window comes back by itself and opens the tool.`, Theme.Text)
			teleportFailed = function(reason: string)
				setStatus(`Can't teleport to {entry.name}: {reason}`, Theme.Danger)
			end
			local ok, err = joinGame(entry)
			if not ok then
				setStatus(`Teleport failed: {err}`, Theme.Danger)
			end
		end
		busy = false
	end))
end

create("TextLabel", {
	Size = UDim2.new(1, 0, 0, 0),
	AutomaticSize = Enum.AutomaticSize.Y,
	BackgroundTransparency = 1,
	Text = "Tip: some games don't allow teleporting to other games. If Join says so, open that game from Roblox and run this script again.",
	TextColor3 = Theme.SubText,
	FontFace = Theme.Font,
	TextSize = 11,
	TextWrapped = true,
	TextXAlignment = Enum.TextXAlignment.Left,
	LayoutOrder = 99,
	Parent = body,
})

local closeBtn = create("TextButton", {
	Size = UDim2.new(1, 0, 0, 30),
	BackgroundColor3 = Theme.Field,
	AutoButtonColor = false,
	BorderSizePixel = 0,
	Text = "Close this window",
	TextColor3 = Theme.Text,
	FontFace = Theme.FontBold,
	TextSize = 13,
	LayoutOrder = 100,
	Parent = body,
}, {
	create("UICorner", { CornerRadius = Theme.Corner }),
})
hoverTween(closeBtn, Theme.Field, Theme.FieldHover)

window.Parent = screen

----------------------------------------------------------------------------------------------------
-- Dragging + toggle key
----------------------------------------------------------------------------------------------------
local drag = { active = false, startMouse = Vector2.zero, startPos = UDim2.new() }
give(titleBar.InputBegan:Connect(function(input: InputObject)
	local t = input.UserInputType
	if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
		drag.active = true
		drag.startMouse = Vector2.new(input.Position.X, input.Position.Y)
		drag.startPos = window.Position
	end
end))
give(UserInputService.InputChanged:Connect(function(input: InputObject)
	if not drag.active then
		return
	end
	local t = input.UserInputType
	if t ~= Enum.UserInputType.MouseMovement and t ~= Enum.UserInputType.Touch then
		return
	end
	local delta = Vector2.new(input.Position.X, input.Position.Y) - drag.startMouse
	local start = drag.startPos
	window.Position = UDim2.new(start.X.Scale, start.X.Offset + delta.X, start.Y.Scale, start.Y.Offset + delta.Y)
end))
give(UserInputService.InputEnded:Connect(function(input: InputObject)
	local t = input.UserInputType
	if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
		drag.active = false
	end
end))
give(UserInputService.InputBegan:Connect(function(input: InputObject, gameProcessed: boolean)
	if gameProcessed then
		return
	end
	if input.KeyCode == Theme.TOGGLE_KEY then
		window.Visible = not window.Visible
	end
end))

----------------------------------------------------------------------------------------------------
-- Cleanup + controller
----------------------------------------------------------------------------------------------------
local controller = {}
function controller.Cleanup()
	cleanupMaid()
	if genv.__DRAW_HUB == controller then
		genv.__DRAW_HUB = nil
	end
end
controller.Games = GAMES
controller.Join = function(name: string)
	for _, entry in GAMES do
		if entry.name == name then
			return joinGame(entry)
		end
	end
	return false, "unknown game"
end
give(closeBtn.Activated:Connect(controller.Cleanup))
genv.__DRAW_HUB = controller

----------------------------------------------------------------------------------------------------
-- Auto-launch: already inside a listed game (fresh run or just teleported here) → start its drawer.
----------------------------------------------------------------------------------------------------
if here then
	setStatus(`You're in {here.name}: opening its tool…`, Theme.Text)
	task.defer(function()
		if not LocalPlayer.Character then
			LocalPlayer.CharacterAdded:Wait()
		end
		local ok, err = runScript(here.file)
		if genv.__DRAW_HUB ~= controller then
			return -- hub was closed meanwhile
		end
		setStatus(if ok then `{here.name} tool is open. Pick another game to switch, or close this window (RightCtrl brings it back).` else `Error: {err}`, if ok then Theme.Good else Theme.Danger)
	end)
end

